'use client';import { useState } from 'react';import { useRouter } from 'next/navigation';import { Agent,Status,Ticket } from '@/types';import { api } from '@/lib/api';export function TicketActions({ticket,agents}:{ticket:Ticket;agents:Agent[]}){const [agent,setAgent]=useState(String(ticket.agent_id??'')),[status,setStatus]=useState<Status>(ticket.status),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);const r=useRouter();async function run(fn:()=>Promise<unknown>){try{setBusy(true);setMsg('');await fn();setMsg('Updated successfully.');r.refresh()}catch(e){setMsg(e instanceof Error?e.message:'Update failed')}finally{setBusy(false)}}return <div className="card space-y-5 p-5"><h2 className="text-xl font-bold">Manage Ticket</h2><label className="block">Assigned Agent<select className="field mt-1" value={agent} onChange={e=>setAgent(e.target.value)}><option value="">Unassigned</option>{agents.filter(a=>a.status==='ACTIVE').map(a=><option value={a.id} key={a.id}>{a.name} — {a.department}</option>)}</select></label><button disabled={!agent||busy} className="btn btn-primary w-full disabled:opacity-50" onClick={()=>run(()=>api.assign(ticket.id,Number(agent)))}>Assign Agent</button><label className="block">Status<select className="field mt-1" value={status} onChange={e=>setStatus(e.target.value as Status)}>{['OPEN','IN_PROGRESS','RESOLVED','CLOSED'].map(x=><option key={x}>{x}</option>)}</select></label><button disabled={busy||status===ticket.status} className="btn btn-primary w-full disabled:opacity-50" onClick={()=>run(()=>api.status(ticket.id,status))}>Update Status</button>{msg&&<p className="text-sm text-slate-600">{msg}</p>}</div>}
